using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace FileCompass {
 internal static class RenameFluentTests {
  static void Pump(){NavigationTests.Wait(Task.Delay(120));}
  static void Open(Window w){if(w is BatchRenameWindow){w.MaxWidth=Double.PositiveInfinity;w.MaxHeight=Double.PositiveInfinity;}w.Left=-18000;w.Top=-18000;w.ShowActivated=false;w.Show();Pump();w.UpdateLayout();}
  static bool OutlineVisible(Window window,Border frame,double scale){
   var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(window.ActualWidth*scale),(int)Math.Ceiling(window.ActualHeight*scale),96*scale,96*scale,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render((System.Windows.Media.Visual)window.Content);int stride=bitmap.PixelWidth*4;var pixels=new byte[stride*bitmap.PixelHeight];bitmap.CopyPixels(pixels,stride,0);var origin=frame.TranslatePoint(new Point(),window);var ink=FluentColors.SectionLine.Color;var surface=((System.Windows.Media.SolidColorBrush)CompactTheme.PanelSurface).Color;double maxDistance=(Math.Abs(surface.B-ink.B)+Math.Abs(surface.G-ink.G)+Math.Abs(surface.R-ink.R))*.52;
   Func<double,double,bool> matches=delegate(double x,double y){int px=(int)Math.Floor(x*scale),py=(int)Math.Floor(y*scale);if(px<0||py<0||px>=bitmap.PixelWidth||py>=bitmap.PixelHeight)return false;int at=py*stride+px*4;return pixels[at+3]>240&&Math.Abs(pixels[at]-ink.B)+Math.Abs(pixels[at+1]-ink.G)+Math.Abs(pixels[at+2]-ink.R)<=maxDistance;};
   foreach(double fraction in new[]{.25,.5,.75})foreach(int side in new[]{0,1,2,3}){bool found=false;for(double inset=.25;inset<3;inset+=.25){double x=origin.X+(side==0?inset:side==1?frame.ActualWidth-inset:frame.ActualWidth*fraction),y=origin.Y+(side==2?inset:side==3?frame.ActualHeight-inset:frame.ActualHeight*fraction);if(matches(x,y)){found=true;break;}}if(!found)return false;}return true;
  }
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();var windows=new List<Window>();try{System.Threading.SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(System.Windows.Threading.Dispatcher.CurrentDispatcher));Action<bool,string> check=delegate(bool ok,string text){if(!ok)throw new Exception(text);log.Add(text);};L.ChangeLanguage("cs");var main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Width=1440,Height=900};windows.Add(main);Open(main);NavigationTests.WaitPanels(main);
   string fixture=Path.Combine(root,"alpha_alpha.xyz");File.WriteAllText(fixture,"unchanged");var settings=new RenameOptions{Find="alpha",Replace="beta",FirstOnly=true};check(BatchRenameEngine.Preview(new[]{fixture},settings)[0].NewName=="beta_alpha.xyz","first-only replacement preserves subsequent occurrences");settings.FirstOnly=false;check(BatchRenameEngine.Preview(new[]{fixture},settings)[0].NewName=="beta_beta.xyz","default replacement still changes all occurrences");settings=new RenameOptions{Name="[N2-5]_[C]",Extension="[E1-2]",Start=7,Digits=3};check(BatchRenameEngine.Preview(new[]{fixture},settings)[0].NewName=="lpha_007.xy","name/extension ranges and padded counters combine correctly");string preset=Path.Combine(root,"saved.fcrename");settings.FirstOnly=true;RenamePresets.Save(preset,settings);var restored=RenamePresets.Load(preset);check(restored.Name==settings.Name&&restored.Extension==settings.Extension&&restored.FirstOnly&&restored.Start==7&&restored.Digits==3,"preset round trip preserves complete settings");File.WriteAllText(preset,"<!DOCTYPE x [<!ENTITY e SYSTEM 'file:///missing'>]><RenameOptions>&e;</RenameOptions>");bool rejected=false;try{RenamePresets.Load(preset);}catch(InvalidOperationException){rejected=true;}catch(System.Xml.XmlException){rejected=true;}check(rejected,"preset parser rejects DTD and external entities");File.Delete(fixture);
   var brand=FluentUiTests.Children<StackPanel>(main).Single(x=>Convert.ToString(x.Tag)=="main-brand");check(brand.Children.OfType<Image>().Single().Source==main.Icon&&brand.Children.OfType<TextBlock>().Single().Text==ApplicationBrand.Name,"main title uses the live application icon and name");check(!FluentUiTests.Children<TextBlock>(main).Any(x=>x.Text.Contains("Pracovní prostor")),"workspace placeholder is removed from title bar");main.ToggleFluentDrawer();Pump();var footer=FluentUiTests.Children<Border>(main).Single(x=>Convert.ToString(x.Tag)=="drawer-about-footer");check(footer.IsVisible&&DockPanel.GetDock(footer)==Dock.Bottom,"About is pinned at the bottom of the drawer");var menus=FluentUiTests.Children<Menu>(main).ToArray();var help=menus.SelectMany(x=>x.Items.OfType<MenuItem>()).Single(x=>Convert.ToString(x.Header)==L.Text("action.help"));check(!help.Items.OfType<MenuItem>().Any(x=>Convert.ToString(x.Header)==L.Text("app.aboutMenu")),"About is no longer inside Help");NextStageTests.Draw(main,Path.Combine(root,"main-menu.png"));main.CloseFluentDrawer();
   var about=new AboutWindow(main);windows.Add(about);Open(about);var github=FluentUiTests.Children<TextBlock>(about).Single(x=>x.Inlines.Contains(about.Repository));check(github.TranslatePoint(new Point(),about).X>=about.DeveloperLogo.TranslatePoint(new Point(about.DeveloperLogo.ActualWidth,0),about).X+24,"developer links are placed on the right with clear space after logo");NextStageTests.Draw(about,Path.Combine(root,"about.png"));about.Close();windows.Remove(about);
   string[] paths={Path.Combine(root,"Fotografie.txt"),Path.Combine(root,"Dokument.txt")};foreach(string path in paths)File.WriteAllText(path,"fixture:"+Path.GetFileName(path));var rename=new BatchRenameWindow(main,paths,delegate{});windows.Add(rename);Open(rename);NavigationTests.Wait(rename.PreviewTask);var list=AdvancedToolsTests.Visual<ListView>(rename).Single();var name=FluentUiTests.Children<TextBox>(rename).Single(x=>x.GetValue(TokenDropdown.MenuProperty)!=null);var start=FluentUiTests.Children<Button>(rename).Single(x=>Convert.ToString(x.Content)==L.Text("action.start"));
   check(FluentUiTests.Children<Border>(rename).Count(x=>Convert.ToString(x.Tag)=="rename-options-card")==2,"rename options form two coherent Fluent cards");check(!start.IsEnabled,"unchanged preview cannot start renaming");name.Text="[N]_[C]";NavigationTests.Wait(rename.PreviewTask);check(start.IsEnabled&&list.Items.Cast<RenameRow>().All(x=>x.Changed),"mask and counter update the live preview");
   foreach(var size in new[]{new Size(1440,840),new Size(1000,700)}){rename.MaxWidth=Double.PositiveInfinity;rename.MaxHeight=Double.PositiveInfinity;rename.Width=size.Width;rename.Height=size.Height;Pump();rename.UpdateLayout();check(list.ActualHeight>=(size.Width>=1400?180:150),"compact rename reserves more room for file rows at "+size+"; actual="+rename.ActualWidth+"x"+rename.ActualHeight+"; list="+list.ActualHeight);var previewFrame=FluentUiTests.Children<Border>(rename).Single(x=>Convert.ToString(x.Tag)=="rename-preview-card");foreach(var optionsFrame in FluentUiTests.Children<Border>(rename).Where(x=>Convert.ToString(x.Tag)=="rename-options-card"))check(optionsFrame.TranslatePoint(new Point(0,optionsFrame.ActualHeight),rename).Y<previewFrame.TranslatePoint(new Point(),rename).Y,"options bottom outline stays above the preview at "+size);var actionFooter=FluentUiTests.Children<Border>(rename).Single(x=>Convert.ToString(x.Tag)=="dialog-footer");check(start.TranslatePoint(new Point(0,start.ActualHeight),rename).Y<=actionFooter.TranslatePoint(new Point(0,actionFooter.ActualHeight),rename).Y,"primary rename action remains inside footer at "+size);foreach(double scale in new[]{1.0,1.25,1.5})foreach(var frame in FluentUiTests.Children<Border>(rename).Where(x=>Convert.ToString(x.Tag)=="rename-options-card"||Convert.ToString(x.Tag)=="rename-preview-card"))check(OutlineVisible(rename,frame,scale),"all four frame edges remain visible at "+scale+" scale and "+size);NextStageTests.Draw(rename,Path.Combine(root,"rename-"+size.Width+".png"));}
   check(!FluentUiTests.Children<Button>(rename).Any(x=>Convert.ToString(x.Content)==L.Text("rename.namePart")),"redundant separate name-part action is removed");
   var paletteCard=FluentUiTests.Children<Border>(rename).First(x=>Convert.ToString(x.Tag)=="rename-options-card");var previousColor=((System.Windows.Media.SolidColorBrush)paletteCard.Background).Color;FluentColors.Select("mint");Pump();check(((System.Windows.Media.SolidColorBrush)paletteCard.Background).Color!=previousColor,"rename cards follow the selected application palette");NextStageTests.Draw(rename,Path.Combine(root,"rename-mint.png"));FluentColors.Select("azure");Pump();
   name.Select(0,3);var insert=FluentUiTests.Children<Button>(rename).Single(x=>Convert.ToString(x.Content)==L.Text("rename.insertToken"));insert.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var tokens=(ContextMenu)name.GetValue(TokenDropdown.MenuProperty);check(tokens.IsOpen,"explicit token picker opens the existing token menu");tokens.IsOpen=false;
   name.Text=":";NavigationTests.Wait(rename.PreviewTask);check(!start.IsEnabled,"invalid mask blocks rename while retaining preview");name.Text="[N]_[C]";NavigationTests.Wait(rename.PreviewTask);start.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var until=DateTime.UtcNow.AddSeconds(5);while(!File.Exists(Path.Combine(root,"Fotografie_1.txt"))&&DateTime.UtcNow<until)Pump();Pump();check(File.ReadAllText(Path.Combine(root,"Fotografie_1.txt"))=="fixture:Fotografie.txt"&&File.Exists(Path.Combine(root,"Dokument_2.txt")),"new UI performs actual rename without changing file contents");var undo=FluentUiTests.Children<Button>(rename).Single(x=>Convert.ToString(x.Content)==L.Text("rename.undoLastChange"));check(undo.IsEnabled,"successful rename enables undo");undo.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));until=DateTime.UtcNow.AddSeconds(5);while(!File.Exists(paths[0])&&DateTime.UtcNow<until)Pump();Pump();check(paths.All(File.Exists)&&!File.Exists(Path.Combine(root,"Fotografie_1.txt")),"undo restores the original names");rename.Close();windows.Remove(rename);main.Close();windows.Remove(main);File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}finally{foreach(var w in windows.ToArray().Reverse())w.Close();}}
 }
}
